from scipy.optimize import least_squares
def nmse(p,f):
    return np.mean((f(p)-dP_dt)**2)/np.var(dP_dt)
models={
 'MM': lambda p: p[0]*P/(p[1]+P),
 'MM-linear': lambda p: p[0]*P/(p[1]+P)-p[2]*P,
 'MM-t': lambda p: p[0]*P/(p[1]+P)*(1+p[2]*np.sin(p[3]*t+p[4])),
 'MM-tdecay': lambda p: p[0]*P/(p[1]+P)*np.exp(-p[2]*t),
 'MM-tlin': lambda p: (p[0]+p[2]*t)*P/(p[1]+P),
}
for k,f in models.items():
    best=None
    for s in range(30):
        p0=np.random.rand(5)*3
        try:
            sol=least_squares(lambda p: f(p)-dP_dt, p0)
            if best is None or sol.cost<best.cost: best=sol
        except Exception as e: pass
    print(k, np.mean((f(best.x)-dP_dt)**2)/np.var(dP_dt), np.round(best.x,4))

y=dP_dt
def fitnm(cols):
    A=np.column_stack(cols); c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
    return np.mean((A@c-y)**2)/np.var(y), np.round(c,4)
for k in range(2,7):
    print('poly',k, fitnm([P**j for j in range(1,k+1)]))
print('MM-like', fitnm([P, P**2, P**3, P*t, P**2*t]))
print('logs', fitnm([P, P*np.log(P), P**2, P*np.sqrt(P), P**2*np.log(P)]))
print('rat', fitnm([P, P**2, P**2/(1+P), P/(1+P), P*P/(0.5+P)]))

